irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    int port;

    spin_lock(&i8042_lock);
    status = inb_p(0x64);
    data = inb_p(0x60);

    if (status & 0x80) {
        /* MUX error or timeout */
        spin_unlock(&i8042_lock);
        return IRQ_NONE;
    }

    port = i8042_get_port_from_status(status);
    if (port < 0) {
        spin_unlock(&i8042_lock);
        return IRQ_NONE;
    }

    if (i8042_filter[port](data)) {
        spin_unlock(&i8042_lock);
        return IRQ_NONE;
    }

    i8042_pass_data(data, port);
    spin_unlock(&i8042_lock);

    return IRQ_HANDLED;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    int handled = 0;
    struct serio *port;

    spin_lock(&i8042_lock);
    status = inb(I8042_STATUS);
    if (status & I8042_OBF) {
        data = inb(I8042_DATA);
        handled = 1;

        if (status & (I8042_MUXERR | I8042_TIMEOUT)) {
            i8042_flush();
            handled = 0;
        } else {
            port = i8042_get_port();
            if (port && !i8042_filter(data))
                serio_interrupt(port, data, 0);
        }
    }
    spin_unlock(&i8042_lock);

    return handled ? IRQ_HANDLED : IRQ_NONE;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    int handled = 0;

    spin_lock(&i8042_lock);
    status = inb_p(PortStatus);
    if (status & 0x80) {
        data = inb_p(DataPort);

        if (status & 0x01) {
            /*MUX error or timeout*/
        } else {
            int i;
            for (i = 0; i < 4; i++) {
                if (i8042_ports[i].handler && (i8042_ports[i].str & 0x0f) == (data & 0x0f)) {
                    if (i8042_filter && i8042_filter(data)) {
                        serio_interrupt(&i8042_ports[i], data, 0);
                        handled = 1;
                    }
                }
            }
        }
    }
    spin_unlock(&i8042_lock);

    return handled ? IRQ_HANDLED : IRQ_NONE;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    struct serio *port;

    spin_lock(&i8042_lock);

    status = inb_p(STATUS_PORT);
    if (status & (ST_PARITY | ST_TIMEOUT))
        goto out;

    if (status & ST_MOUSE_INT)
        port = i8042_mouse_port;
    else
        port = i8042_kbd_port;

    data = inb_p(DATA_PORT);

    if (i8042_filter && i8042_filter(data, port))
        goto out;

    serio_interrupt(port, data, 0);

out:
    spin_unlock(&i8042_lock);

    return IRQ_HANDLED;
}

irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
    unsigned char status, data;
    int handled = 0;

    spin_lock(&i8042_lock);

    status = inb_p(STATUS_PORT);
    if (status & OBF) {
        data = inb_p(DATA_PORT);

        if (status & (MUXERR | TIMEOUT)) {
            if (status & MUXERR)
                printk(KERN_ERR "i8042: MUX error\n");
            if (status & TIMEOUT)
                printk(KERN_ERR "i8042: Timeout error\n");
        } else {
            int port;

            port = i8042_mux_port(status);
            if (port >= 0 && port < i8042_num_ports) {
                struct serio *serio = &i8042_ports[port];
                if (!serio->drv)
                    i8042_filter(serio, data);
                else
                    serio_interrupt(serio, data, 0);
                handled = 1;
            }
        }
    }

    spin_unlock(&i8042_lock);

    return handled ? IRQ_HANDLED : IRQ_NONE;
}
